#include "fixture_authorization_frame.h"
#include "synthetic_resource_contract.h"
#include <assert.h>
#include <string.h>
#include <stdio.h>
static void packet(unsigned char*out,const char*json,size_t*length){size_t n=strlen(json);memcpy(out,"AXQAUTH1",8);memcpy(out+8,AX_SYNTH_GENERATION,32);for(unsigned i=0;i<4;i++)out[40+i]=(unsigned char)(n>>(24-i*8));memcpy(out+44,json,n);*length=n+44;}
int main(int argc,char**argv){unsigned char bytes[AX_FIXTURE_AUTH_FRAME_MAX];AxFixtureAuthorization out;size_t n;const char*invalid[]={"{}","{\"tenant\":\"qualification_workspace\",\"tenant\":\"qualification_workspace\"}","{\"tenant\":\"qualification_workspace\",\"\\u0074enant\":\"qualification_workspace\"}","{\"unexpected\":true}","{\"tenant\":\"qualification_workspace\",\"scenarios\":[]}","{\"tenant\":\"qualification_workspace\",\"requesterToken\":\"fake\"}","{\"tenant\":\"qualification_workspace\"} extra"};for(unsigned i=0;i<sizeof invalid/sizeof invalid[0];i++){packet(bytes,invalid[i],&n);assert(!ax_fixture_authorization_decode(bytes,n,&out));}packet(bytes,"{}",&n);bytes[44]=0xff;assert(!ax_fixture_authorization_decode(bytes,n,&out));packet(bytes,"{}",&n);bytes[40]=1;assert(!ax_fixture_authorization_decode(bytes,n,&out));AxFixtureAuthorizationStream stream={0};assert(!ax_fixture_authorization_stream_feed(&stream,bytes,sizeof bytes));assert(stream.failed);if(argc==2){FILE*f=fopen(argv[1],"rb");assert(f);n=fread(bytes,1,sizeof bytes,f);assert(!ferror(f)&&fgetc(f)==EOF);fclose(f);assert(ax_fixture_authorization_decode(bytes,n,&out));unsigned char request[4096];size_t size;unsigned budget;for(size_t i=0;i<out.count;i++){assert(ax_fixture_scenario_request(&out,i,request,sizeof request,&size,&budget));assert(size<=4096);assert(strstr((char*)request,out.requester_token));}ax_fixture_authorization_wipe(&out);}return 0;}
